package com.erudit.notificator.repository;import com.erudit.notificator.model.*;import java.time.*;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository @RequiredArgsConstructor public class DeliveryRepository {private final JdbcClient jdbc;
 public List<NotificationRecord> pending(int limit){return jdbc.sql("SELECT n.* FROM notifications n WHERE NOT EXISTS(SELECT 1 FROM delivery_attempts d WHERE d.notification_id=n.id AND d.status='MOCK_DELIVERED') ORDER BY n.created_at LIMIT :limit").param("limit",limit).query((r,n)->new NotificationRecord(r.getObject("id",UUID.class),r.getObject("user_id",UUID.class),r.getString("template_code"),r.getString("title"),r.getString("body"),r.getTimestamp("read_at")!=null,r.getTimestamp("created_at").toInstant().atOffset(ZoneOffset.UTC))).list();}
 public long deliveredToday(UUID user){return jdbc.sql("SELECT count(*) FROM delivery_attempts d JOIN notifications n ON n.id=d.notification_id WHERE n.user_id=:user AND d.status='MOCK_DELIVERED' AND d.created_at>=CURRENT_DATE").param("user",user).query(Long.class).single();}
 public DeliveryAttempt record(NotificationRecord n,String status){int attempt=jdbc.sql("SELECT count(*) FROM delivery_attempts WHERE notification_id=:id").param("id",n.id()).query(Integer.class).single()+1;String text=n.title()+": "+n.body(),preview=text.substring(0,Math.min(500,text.length()));var v=new DeliveryAttempt(UUID.randomUUID(),n.id(),attempt,status,preview,OffsetDateTime.now(ZoneOffset.UTC));jdbc.sql("INSERT INTO delivery_attempts(id,notification_id,attempt,status,payload_preview,created_at) VALUES(:id,:notification,:attempt,:status,:preview,:created)").param("id",v.id()).param("notification",n.id()).param("attempt",attempt).param("status",status).param("preview",preview).param("created",v.createdAt()).update();return v;}
 public List<DeliveryAttempt> attempts(UUID notification){return jdbc.sql("SELECT * FROM delivery_attempts WHERE notification_id=:id ORDER BY attempt").param("id",notification).query((r,n)->new DeliveryAttempt(r.getObject("id",UUID.class),notification,r.getInt("attempt"),r.getString("status"),r.getString("payload_preview"),r.getObject("created_at",OffsetDateTime.class))).list();}
}
